Watermarking Pipeline
Diagram 1: Digital watermarking pipeline
\usetikzlibrary{arrows.meta}
\begin{tikzpicture}[&gt;=Latex, font=\small]

% Message m (top left)
\node at (2.0, 7.5) {Message $m$};
\draw[-&gt;] (2.0, 7.3) -- (2.0, 6.7);

% Encoder
\draw[fill=green!40, draw=green!60!black] (0.5, 5.7) rectangle (3.5, 6.7);
\node at (2.0, 6.2) {\textbf{Encoder}};

% Image x
\node at (-0.8, 4.2) {$\mathbf{x}$};
\draw[-&gt;] (-0.3, 4.2) -- (0.5, 4.2);

% s: Encoder -&gt; Embedder
\draw[-&gt;] (2.0, 5.7) -- (2.0, 4.7);
\node at (2.4, 5.2) {$\mathbf{s}$};

% Key k (left)
\node at (2.0, 1.5) {Key $k$};
\draw[-&gt;] (2.0, 1.8) -- (2.0, 2.8);

% Embedder
\draw[fill=green!40, draw=green!60!black] (0.5, 2.8) rectangle (3.5, 4.7);
\node at (2.0, 3.75) {\textbf{Embedder}};

% y: Embedder -&gt; Channel
\draw[-&gt;] (3.5, 4.0) -- (5.5, 4.0);
\node at (4.5, 4.3) {$\mathbf{y}$};

% Multimedia Channel
\draw[fill=blue!30, draw=blue!70!black] (5.5, 3.0) rectangle (8.0, 5.0);
\node at (6.75, 4.3) {\textbf{Multimedia}};
\node at (6.75, 3.7) {\textbf{Channel}};

% v: Channel -&gt; Extractor
\draw[-&gt;] (8.0, 4.0) -- (9.5, 4.0);
\node at (8.75, 4.3) {$\mathbf{v}$};

% Extractor
\draw[fill=green!40, draw=green!60!black] (9.5, 2.8) rectangle (12.0, 4.7);
\node at (10.75, 3.75) {\textbf{Extractor}};

% Key k (right)
\node at (10.75, 1.5) {Key $k$};
\draw[-&gt;] (10.75, 1.8) -- (10.75, 2.8);

% s-hat: Extractor -&gt; Decoder
\draw[-&gt;] (10.75, 4.7) -- (10.75, 5.7);
\node at (11.2, 5.2) {$\hat{\mathbf{s}}$};

% Decoder
\draw[fill=green!40, draw=green!60!black] (9.5, 5.7) rectangle (12.0, 6.7);
\node at (10.75, 6.2) {\textbf{Decoder}};

% Message m-hat (top right)
\node at (10.75, 7.5) {Message $\hat{m}$};
\draw[-&gt;] (10.75, 6.7) -- (10.75, 7.3);

\end{tikzpicture}

Perceptual Hashing Pipeline
Diagram 2: Perceptual hashing and BSC channel model
\usetikzlibrary{arrows.meta}
\begin{tikzpicture}[&gt;=Latex, font=\small]

% Original image x
\draw[fill=gray!15, draw=gray!60] (0.0, 4.0) rectangle (2.0, 5.5);
\node at (1.0, 4.75) {$\mathbf{x}$};

% x -&gt; Hash
\draw[-&gt;] (2.0, 4.75) -- (3.5, 4.75);

% Hash function h(.,k)
\draw[fill=green!40, draw=green!60!black] (3.5, 4.0) rectangle (6.0, 5.5);
\node at (4.75, 5.0) {\textbf{Hash}};
\node at (4.75, 4.5) {$h(\cdot, k)$};

% Fingerprint bx
\draw[-&gt;] (6.0, 4.75) -- (7.5, 4.75);
\draw[fill=orange!30, draw=orange!60!black] (7.5, 4.0) rectangle (10.0, 5.5);
\node at (8.75, 5.0) {$\mathbf{b}_x \in \{0,1\}^L$};
\node at (8.75, 4.4) {Fingerprint};

% bx -&gt; BSC
\draw[-&gt;] (8.75, 4.0) -- (8.75, 2.8);

% BSC channel
\draw[fill=blue!30, draw=blue!70!black] (7.0, 1.8) rectangle (10.5, 2.8);
\node at (8.75, 2.3) {\textbf{BSC} $(P_b)$};

% BSC -&gt; b-hat-x
\draw[-&gt;] (8.75, 1.8) -- (8.75, 0.8);
\draw[fill=orange!30, draw=orange!60!black] (7.5, 0.0) rectangle (10.0, 0.8);
\node at (8.75, 0.4) {$\hat{\mathbf{b}}_x$};

% Attacked image y
\draw[fill=gray!25, draw=gray!60] (0.0, 0.0) rectangle (2.0, 1.5);
\node at (1.0, 0.9) {$\mathbf{y} = \mathcal{A}(\mathbf{x})$};
\node at (1.0, 0.3) {Attacked};

% y -&gt; Hash2
\draw[-&gt;] (2.0, 0.75) -- (3.5, 0.75);

% Hash function for attacked image
\draw[fill=green!40, draw=green!60!black] (3.5, 0.0) rectangle (6.0, 1.5);
\node at (4.75, 1.0) {\textbf{Hash}};
\node at (4.75, 0.5) {$h(\cdot, k)$};

% by fingerprint
\draw[-&gt;] (6.0, 0.75) -- (7.5, 0.75);
\draw[fill=orange!30, draw=orange!60!black] (7.5, 0.0) rectangle (10.0, 1.5);
\node at (8.75, 1.0) {$\mathbf{b}_y \in \{0,1\}^L$};
\node at (8.75, 0.4) {Direct hash};

\end{tikzpicture}

Cryptographic Hash vs. Perceptual Hash
Diagram 3: Comparison of cryptographic vs. perceptual hashing
\usetikzlibrary{arrows.meta}
\begin{tikzpicture}[&gt;=Latex, font=\small]

% === Left: Cryptographic Hash ===
\node at (2.5, 7.5) {\textbf{Cryptographic Hash (SHA-256)}};
\draw[fill=gray!15, draw=gray!60] (0.5, 6.2) rectangle (4.5, 7.2);
\node at (2.5, 6.7) {Image $\mathbf{x}$};
\draw[-&gt;] (2.5, 6.2) -- (2.5, 5.4);
\draw[fill=blue!30, draw=blue!80!black] (0.5, 4.5) rectangle (4.5, 5.4);
\node at (2.5, 4.95) {\textbf{SHA-256}};
\draw[-&gt;] (2.5, 4.5) -- (2.5, 3.7);
\draw[fill=orange!30, draw=orange!80!black] (0.5, 2.8) rectangle (4.5, 3.7);
\node at (2.5, 3.25) {256-bit hash};

% Avalanche effect
\draw[fill=red!30, draw=red!80!black] (0.5, 1.5) rectangle (4.5, 2.5);
\node at (2.5, 2.1) {\textbf{Avalanche effect:}};
\node at (2.5, 1.7) {1 bit changed $\rightarrow$ 50\% hash changed};

% === Right: Perceptual Hash ===
\node at (9.5, 7.5) {\textbf{Perceptual Hash}};
\draw[fill=gray!15, draw=gray!60] (7.5, 6.2) rectangle (11.5, 7.2);
\node at (9.5, 6.7) {Image $\mathbf{x}$};
\draw[-&gt;] (9.5, 6.2) -- (9.5, 5.4);
\draw[fill=green!40, draw=green!60!black] (7.5, 4.5) rectangle (11.5, 5.4);
\node at (9.5, 4.95) {\textbf{Perceptual Hash} $h(\cdot, k)$};
\draw[-&gt;] (9.5, 4.5) -- (9.5, 3.7);
\draw[fill=orange!30, draw=orange!80!black] (7.5, 2.8) rectangle (11.5, 3.7);
\node at (9.5, 3.25) {$L$-bit fingerprint};

% Robustness
\draw[fill=green!40, draw=green!60!black] (7.5, 1.5) rectangle (11.5, 2.5);
\node at (9.5, 2.1) {\textbf{Robustness:}};
\node at (9.5, 1.7) {JPEG 70\% $\rightarrow$ small Hamming dist.};

\end{tikzpicture}

Adversarial Attacks
An adversarial attack adds a perturbation \(\boldsymbol{\delta}\) to an image \(\mathbf{x}\) that is imperceptible but causes a model \(f\) to make an incorrect prediction:
\[\mathbf{x}^{adv} = \mathbf{x} + \boldsymbol{\delta}, \quad \|\boldsymbol{\delta}\|_\infty \leq \epsilon, \quad f(\mathbf{x}^{adv}) \neq f(\mathbf{x})\]
Diagram 4: Two cases of adversarial attacks
\usetikzlibrary{arrows.meta}
\begin{tikzpicture}[&gt;=Latex, font=\small]

% === Case 1: White-box Attack ===
\node at (3.0, 7.5) {\textbf{Case 1: White-box Attack}};

\draw[fill=gray!15, draw=gray!60] (0.5, 6.0) rectangle (2.5, 7.0);
\node at (1.5, 6.5) {Image $\mathbf{x}$};

\draw[fill=orange!30, draw=orange!80!black] (0.5, 4.5) rectangle (2.5, 5.5);
\node at (1.5, 5.0) {Perturbation $\boldsymbol{\delta}$};

\draw[-&gt;] (1.5, 6.0) -- (1.5, 5.5);

\draw[fill=red!30, draw=red!80!black] (0.0, 3.2) rectangle (3.0, 4.2);
\node at (1.5, 3.7) {$\mathbf{x}^{adv} = \mathbf{x} + \boldsymbol{\delta}$};
\draw[-&gt;] (1.5, 4.5) -- (1.5, 4.2);

\draw[-&gt;] (1.5, 3.2) -- (1.5, 2.5);
\draw[fill=blue!30, draw=blue!80!black] (0.0, 1.5) rectangle (3.0, 2.5);
\node at (1.5, 2.1) {\textbf{Model $f$}};
\node at (1.5, 1.7) {(known gradient)};

\draw[-&gt;] (1.5, 1.5) -- (1.5, 0.8);
\draw[fill=red!30, draw=red!80!black] (0.0, 0.0) rectangle (3.0, 0.8);
\node at (1.5, 0.4) {Wrong prediction};

% === Case 2: Black-box Attack (Transfer) ===
\node at (9.0, 7.5) {\textbf{Case 2: Black-box Attack (Transfer)}};

\draw[fill=gray!15, draw=gray!60] (6.5, 6.0) rectangle (8.5, 7.0);
\node at (7.5, 6.5) {Image $\mathbf{x}$};

\draw[fill=orange!30, draw=orange!80!black] (6.5, 4.5) rectangle (8.5, 5.5);
\node at (7.5, 5.05) {Perturbation $\boldsymbol{\delta}$};
\node at (7.5, 4.65) {(on surrogate)};

\draw[-&gt;] (7.5, 6.0) -- (7.5, 5.5);

\draw[fill=red!30, draw=red!80!black] (6.0, 3.2) rectangle (9.0, 4.2);
\node at (7.5, 3.7) {$\mathbf{x}^{adv}$};
\draw[-&gt;] (7.5, 4.5) -- (7.5, 4.2);

\draw[-&gt;] (9.0, 3.7) -- (10.5, 3.7);
\draw[fill=blue!30, draw=blue!80!black] (10.5, 3.2) rectangle (13.0, 4.2);
\node at (11.75, 3.75) {\textbf{Model $f'$}};
\node at (11.75, 3.35) {(unknown)};

\draw[-&gt;] (11.75, 3.2) -- (11.75, 2.5);
\draw[fill=red!30, draw=red!80!black] (10.5, 1.5) rectangle (13.0, 2.5);
\node at (11.75, 2.05) {Transferable};
\node at (11.75, 1.65) {wrong prediction};

\end{tikzpicture}

